def table(headers,rows,caption,searchable=False):
 body=''
 for row in rows:
  cells=row['cells']if isinstance(row,dict)else row
  attrs=''
  if isinstance(row,dict):attrs=' data-search="'+h(row.get('search',' '.join(re.sub('<[^>]+>',' ',str(v))for v in cells)))+'" data-family="'+h(row.get('family',''))+'"'
  body+='<tr'+attrs+'>'+''.join(f'<{"th scope=\"row\"" if i==0 else "td"}>{v}</{"th" if i==0 else "td"}>'for i,v in enumerate(cells))+'</tr>'
 return '<div class="ref-table-wrap" role="region" tabindex="0" aria-label="'+h(caption)+'"><table'+(' data-reference-table'if searchable else'')+'><caption>'+h(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+h(x)+'</th>'for x in headers)+'</tr></thead><tbody>'+body+'</tbody></table></div>'
def filtered(headers,rows,caption,options=None,label='Product family'):
 ident='filter-'+slug(caption)
 controls='<div class="ref-filters" data-reference-filters hidden><div class="ref-search"><label for="'+ident+'">Search this table</label><input type="search" id="'+ident+'" data-reference-search placeholder="Enter a part number, term or dimension"></div>'
 if options:controls+='<div><label for="'+ident+'-family">'+h(label)+'</label><select id="'+ident+'-family" data-reference-family><option value="">All</option>'+''.join('<option>'+h(x)+'</option>'for x in options)+'</select></div>'
 controls+='<button class="ref-clear" type="button" data-reference-clear>Clear filters</button></div><p class="ref-count" data-reference-count role="status" aria-live="polite"></p><p data-reference-empty hidden>No matching entries. Clear the filters or try a shorter search.</p>'
 return '<div data-reference-block>'+controls+table(headers,rows,caption,True)+'</div>'
def series_table(items,caption):
 rows=[]
 for r in items:
  resource=r['guide']or familyfile(r['family'])
  cells=[f'<a href="{resource}">{r["root"]}</a>',h(r['description']),h(r['family']),f'<a href="{resource}">'+('Read guide →'if r['guide']else'Family reference →')+'</a>']
  rows.append({'cells':cells,'search':' '.join([r['root'],r['description'],r['family'],r['aliases'],'stainless'if'corrosion-resistant'in r['description']else'']),'family':r['family']})
 return filtered(['Series','Product description','Family','Resource'],rows,caption,sorted(set(r['family']for r in items)))
def kv(rows,caption):return table(['Item','Reference'],rows,caption)
