body=section('Official document status and successors','<p>These rows identify document status and named successors. A successor document does not by itself establish an approved part substitution. Active entries are included to help resolve assumptions about MS-to-NASM changes.</p><p class="ref-verified">Original records checked October 17, 2026; MS51021 and MS21083 added and checked October 22, 2026.</p>'+filtered(['Reference','Status / named successor','Hardware family'],trs,'Specification status and cross-reference table',['Active','Canceled'],'Document status'),'DOCUMENT REFERENCES')
